
%% ========================================================================
% QUADRATIC NULL-SPACE EXPERIMENT DATA PROCESSING
% =========================================================================
% Analysis of experimental data generated by u_openloop_null_SO
%
% 1. Pressure tracking
% 2. Quadratic model prediction vs measured configuration
% 3. Steady-state configuration vs null-space coordinate
% 4. Effective stiffness from repeated loaded/unloaded trials
%
% =========================================================================

% clear all; close all; clc;

%% ========================================================================
% SETUP
% =========================================================================

% Physical parameters
l1 = 0.122;            % Length of limb 1 [m]
l2 = 0.122;            % Length of limb 2 [m]
epsilon = 1e-6;

% Force plate parameters
k = 11.16;
Fmax = 11.16*1.6/100;

% Experiment timing [s]
initial_wait = 5;
hold_time = 60;
reset_time = 20;

% Desired equilibrium configuration [deg]
q_des = 40;

% Null-space sweep
z_step = 40; % 10 change to match experiment
num_z_values = 5; % 10 change to match experiment 
repetitions = 2;

% Steady-state averaging window [s]
steady_window = 15;

% Pressure limits [hPa gauge]
p_min = 0;
p_max = 250;

%% ========================================================================
% IDENTIFIED QUADRATIC MODEL
% =========================================================================

% q_deg = beta0 + beta1*p1 + beta2*p2 ...
%       + beta3*p1^2 + beta4*p1*p2 + beta5*p2^2

beta0 = 0.506263;
beta1 = 0.347200;
beta2 = -0.223037;
beta3 = 0.000184;
beta4 = 0.002320;
beta5 = -0.002814;

beta = [beta0 beta1 beta2 beta3 beta4 beta5];

%% ========================================================================
% LOAD EXPERIMENTAL DATA
% =========================================================================

% Replace with the quadratic model experiment file
RTJ_file = 'data/ezloophw_self_stiffening_2026-11-11_40fQMv2.csv';

RTJ = readtable(RTJ_file, ...
    'HeaderLines',2, ...
    'VariableNamingRule','preserve');

%% ========================================================================
% EXTRACT EXPERIMENTAL VARIABLES
% =========================================================================

% Time
time_all = RTJ.("Test time");

% Measured angles
theta_0_all = RTJ.theta_0;
theta_1_all = RTJ.theta_1;

% Commanded pressures
u0_all = RTJ.("u_t(0)");
u1_all = RTJ.("u_t(1)");
u2_all = RTJ.("u_t(2)");
u3_all = RTJ.("u_t(3)");

% Determine experimental data interval
%
% Use nonzero commanded pressures to identify the experiment.
% This assumes the experiment includes commanded pressure on
% the first limb.

active_idx = find( ...
    isfinite(u0_all) & isfinite(u1_all) & ...
    ((abs(u0_all) > 1e-6) | (abs(u1_all) > 1e-6)));

if isempty(active_idx)
    error('No active pressure commands found.');
end

startidx = active_idx(1);
endidx = active_idx(end);

% Extract and normalize time
time = time_all(startidx:endidx);
time = time-time(1);
time = time(:);

% Extract angles
theta_0 = theta_0_all(startidx:endidx);
theta_1 = theta_1_all(startidx:endidx);

% Extract pressure commands
u0 = u0_all(startidx:endidx);
u1 = u1_all(startidx:endidx);
u2 = u2_all(startidx:endidx);
u3 = u3_all(startidx:endidx);

% Convert measured angles from degrees to radians
q0_rad = deg2rad(theta_0*2);
q1_rad = deg2rad(theta_1*2);

% Smoothed measured configurations [deg]
smooth_q0 = rad2deg( ...
    RTJ.smoothed_q_0(startidx:endidx));

smooth_q1 = rad2deg( ...
    RTJ.smoothed_q_1(startidx:endidx));

smooth_q0 = smooth_q0(:);
smooth_q1 = smooth_q1(:);

%% ========================================================================
% MEASURED CHAMBER PRESSURES
% =========================================================================

p0_raw = RTJ.MPRpressure_0(startidx:endidx);
p1_raw = RTJ.MPRpressure_1(startidx:endidx);
p2_raw = RTJ.MPRpressure_2(startidx:endidx);
p3_raw = RTJ.MPRpressure_3(startidx:endidx);

% Convert measured pressures to gauge pressures.
%
% IMPORTANT:
% This follows the zero-offset convention of your
% original processing script.
%
% If your pressure sensors are absolute pressure sensors,
% or your controller uses a different calibration baseline,
% replace this with the corresponding calibration.

p0 = p0_raw-p0_raw(1);
p1 = p1_raw-p1_raw(1);
p2 = p2_raw-p2_raw(1);
p3 = p3_raw-p3_raw(1);

%% ========================================================================
% QUADRATIC MODEL PREDICTION
% =========================================================================

% Predicted angle using measured chamber pressures

Predict_angle = beta0 ...
    + beta1*p0 ...
    + beta2*p1 ...
    + beta3*p0.^2 ...
    + beta4*p0.*p1 ...
    + beta5*p1.^2;

% Predicted angle using commanded chamber pressures

Predict_angle_cmd = beta0 ...
    + beta1*u0 ...
    + beta2*u1 ...
    + beta3*u0.^2 ...
    + beta4*u0.*u1 ...
    + beta5*u1.^2;

% Configuration prediction error
q_error = smooth_q0-Predict_angle;

%% ========================================================================
% FIGURE 1: PRESSURE TRACKING AND CONFIGURATION PREDICTION
% =========================================================================

figure('Color','w');

subplot(3,1,1)

plot(time,u0,'LineWidth',1.5);
hold on;
plot(time,p0,'LineWidth',1.2);

ylabel('$p_1$ (hPa)','Interpreter','latex');
title('Chamber 1 Pressure Tracking');

legend('Commanded','Measured', ...
    'Location','best');

grid on;
box off;

subplot(3,1,2)

plot(time,u1,'LineWidth',1.5);
hold on;
plot(time,p1,'LineWidth',1.2);

ylabel('$p_2$ (hPa)','Interpreter','latex');
title('Chamber 2 Pressure Tracking');

legend('Commanded','Measured', ...
    'Location','best');

grid on;
box off;

subplot(3,1,3)

plot(time,Predict_angle,'LineWidth',1.5);
hold on;

plot(time,smooth_q0,'LineWidth',1.2);

yline(q_des,'--','LineWidth',1.2);

xlabel('Time (s)');
ylabel('$q_1$ (deg)','Interpreter','latex');

title('Quadratic Model Prediction vs Measured Configuration');

legend('Quadratic prediction','Measured', ...
    'Desired','Location','best');

grid on;
box off;

%% ========================================================================
% FIGURE 2: MODEL PREDICTION ERROR
% =========================================================================

figure('Color','w');

plot(time,q_error,'LineWidth',1.5);
hold on;

yline(0,'--');

xlabel('Time (s)');
ylabel('$q_{\mathrm{meas}}-\hat{q}$ (deg)', ...
    'Interpreter','latex');

title('Quadratic Model Configuration Prediction Error');

grid on;
box off;

%% ========================================================================
% STEADY-STATE CONFIGURATION EXTRACTION
% =========================================================================

% Experimental null-space coordinates
%
% ode45 integrates from z=0 to z=(num_z_values-1)*z_step.
% These are the experimental arc-length coordinates.

z_unique = (0:num_z_values-1)*z_step;

% Repeat each coordinate to match controller schedule
z_values = repelem(z_unique,repetitions);

num_trials = num_z_values*repetitions;

trial_duration = hold_time+reset_time;

% Steady-state results
q_steady = nan(num_trials,1);
q_pred_steady = nan(num_trials,1);

p0_steady = nan(num_trials,1);
p1_steady = nan(num_trials,1);

u0_steady = nan(num_trials,1);
u1_steady = nan(num_trials,1);

% Extract steady-state data from final portion of each hold

for i = 1:num_trials

    t_start = initial_wait+(i-1)*trial_duration;
    t_end = t_start+hold_time;

    idx = time >= (t_end-steady_window) & ...
          time < t_end;

    if any(idx)

        % Measured equilibrium configuration
        q_steady(i) = mean( ...
            smooth_q0(idx),'omitnan');

        % Model prediction
        q_pred_steady(i) = mean( ...
            Predict_angle(idx),'omitnan');

        % Measured pressures
        p0_steady(i) = mean( ...
            p0(idx),'omitnan');

        p1_steady(i) = mean( ...
            p1(idx),'omitnan');

        % Commanded pressures
        u0_steady(i) = mean( ...
            u0(idx),'omitnan');

        u1_steady(i) = mean( ...
            u1(idx),'omitnan');

    end

end

%% ========================================================================
% RESULTS TABLE: ALL EXPERIMENTAL TRIALS
% =========================================================================

trial_number = (1:num_trials)';

repetition_number = ...
    mod(trial_number-1,repetitions)+1;

results_trials = table( ...
    trial_number, ...
    z_values(:), ...
    repetition_number, ...
    u0_steady, ...
    u1_steady, ...
    p0_steady, ...
    p1_steady, ...
    q_pred_steady, ...
    q_steady, ...
    'VariableNames', ...
    {'Trial','z_hPa','Repetition', ...
     'u0_hPa','u1_hPa', ...
     'p0_hPa','p1_hPa', ...
     'q_pred_deg','q_measured_deg'});

disp(' ');
disp('QUADRATIC NULL-SPACE EXPERIMENT RESULTS');
disp(results_trials);

%% ========================================================================
% FIGURE 3: STEADY-STATE CONFIGURATION VS NULL-SPACE INPUT
% =========================================================================

figure('Color','w');
hold on;

for r = 1:repetitions

    idx = r:repetitions:num_trials;

    plot(z_unique,q_steady(idx),'o-', ...
        'LineWidth',1.5, ...
        'MarkerSize',7, ...
        'DisplayName',sprintf('Repetition %d',r));

end

yline(q_des,'--', ...
    'LineWidth',1.2, ...
    'DisplayName','Desired configuration');

xlabel('$z$ (hPa)','Interpreter','latex');
ylabel('$q_1$ (deg)','Interpreter','latex');

title('Steady-State Configuration vs Null-Space Input');

legend('Location','best');

grid on;
box off;

%% ========================================================================
% FIGURE 4: MEASURED PRESSURES VS NULL-SPACE INPUT
% =========================================================================

figure('Color','w');

subplot(2,1,1)

plot(z_values,p0_steady,'o', ...
    'MarkerSize',6);
hold on;

plot(z_values,u0_steady,'x', ...
    'MarkerSize',7);

xlabel('$z$ (hPa)','Interpreter','latex');
ylabel('$p_1$ (hPa)','Interpreter','latex');

title('Chamber 1 Steady-State Pressure');

legend('Measured','Commanded','Location','best');

grid on;
box off;

subplot(2,1,2)

plot(z_values,p1_steady,'o', ...
    'MarkerSize',6);
hold on;

plot(z_values,u1_steady,'x', ...
    'MarkerSize',7);

xlabel('$z$ (hPa)','Interpreter','latex');
ylabel('$p_2$ (hPa)','Interpreter','latex');

title('Chamber 2 Steady-State Pressure');

legend('Measured','Commanded','Location','best');

grid on;
box off;

%% ========================================================================
% EFFECTIVE STIFFNESS CALCULATION
% =========================================================================

% Stiffness estimation requires paired unloaded and loaded
% measurements at the same null-space coordinate.
%
% Repetition 1: unloaded
% Repetition 2: loaded with 50 g mass
%
% If repetitions = 1, this section is skipped.

if repetitions == 2

    %% External applied torque

    mass = 0.010;     % [kg]
    g = 9.81;        % [m/s^2]
    moment_arm = l1; % [m]

    tau_ext = mass*g*moment_arm;

    %% Separate unloaded and loaded measurements

    q_unloaded = q_steady(1:2:end);
    q_loaded = q_steady(2:2:end);

    %% Calculate angular deflection

    delta_q_deg = q_loaded-q_unloaded;

    delta_q_rad = deg2rad(delta_q_deg);

    %% Effective rotational stiffness

    K_eff = tau_ext./abs(delta_q_rad);

    % Exclude nearly zero angular deflections
    K_eff(abs(delta_q_deg)<0.1) = NaN;

    %% Results table

    results_stiffness = table( ...
        z_unique(:), ...
        q_unloaded(:), ...
        q_loaded(:), ...
        delta_q_deg(:), ...
        K_eff(:), ...
        'VariableNames', ...
        {'z_hPa','q_unloaded_deg','q_loaded_deg', ...
         'delta_q_deg','K_eff_Nm_rad'});

    disp(' ');
    disp('EFFECTIVE ROTATIONAL STIFFNESS RESULTS');
    disp(results_stiffness);

    %% ================================================================
    % FIGURE 5: STIFFNESS AND ANGULAR DEFLECTION
    % ================================================================

    figure('Color','w');

    subplot(2,1,1)

    plot(z_unique,K_eff,'o-', ...
        'LineWidth',1.5, ...
        'MarkerSize',7);

    xlabel('$z$ (hPa)','Interpreter','latex');

    ylabel('$K_{\mathrm{eff}}$ (N m/rad)', ...
        'Interpreter','latex');

    title('Effective Rotational Stiffness vs Null-Space Input');

    grid on;
    box off;

    subplot(2,1,2)

    plot(z_unique,delta_q_deg,'o-', ...
        'LineWidth',1.5, ...
        'MarkerSize',7);

    xlabel('$z$ (hPa)','Interpreter','latex');

    ylabel('$\Delta q$ (deg)', ...
        'Interpreter','latex');

    title('Load-Induced Angular Deflection vs Null-Space Input');

    grid on;
    box off;

else

    fprintf('\n');
    fprintf('Stiffness calculation skipped.\n');
    fprintf('Set repetitions = 2 for unloaded/loaded comparison.\n');

end

%% ========================================================================
% SUMMARY STATISTICS
% =========================================================================

valid_idx = isfinite(q_steady);

if any(valid_idx)

    steady_error = q_steady(valid_idx)-q_des;

    fprintf('\n');
    fprintf('QUADRATIC NULL-SPACE EXPERIMENT SUMMARY\n');
    fprintf('----------------------------------------\n');
    fprintf('Desired configuration: %.3f deg\n',q_des);
    fprintf('Number of trials: %d\n',num_trials);

    fprintf('Mean steady-state error: %.4f deg\n', ...
        mean(steady_error));

    fprintf('Maximum absolute steady-state error: %.4f deg\n', ...
        max(abs(steady_error)));

    fprintf('Standard deviation of measured configuration: %.4f deg\n', ...
        std(q_steady(valid_idx)));

end
